import { Easing, interpolate, spring } from "remotion";

/** House easing curves — nothing in the film moves linearly. */
export const EASE = {
  /** Camera moves: slow start, long graceful settle. */
  cine: Easing.bezier(0.45, 0, 0.2, 1),
  /** Entrances: quick departure, soft landing. */
  out: Easing.bezier(0.16, 1, 0.3, 1),
  /** Symmetric moves (swaps, swings). */
  inOut: Easing.bezier(0.65, 0, 0.35, 1),
  /** Exits: gentle acceleration away. */
  in: Easing.bezier(0.5, 0, 0.75, 0),
};

/** 0→1 over [start, start+dur], clamped and eased. */
export const prog = (frame: number, start: number, dur: number, easing: (t: number) => number = EASE.out): number =>
  interpolate(frame, [start, start + dur], [0, 1], {
    extrapolateLeft: "clamp",
    extrapolateRight: "clamp",
    easing,
  });

/** Spring that lands with a gentle overshoot (or none), starting at `start`. */
export const settle = (frame: number, fps: number, start: number, overshoot = true): number =>
  spring({
    frame: frame - start,
    fps,
    config: overshoot ? { damping: 13, stiffness: 80, mass: 0.9 } : { damping: 200, stiffness: 80 },
  });

export const mix = (a: number, b: number, t: number): number => a + (b - a) * t;

/** Seconds → frames at 30 fps. */
export const sec = (s: number): number => Math.round(s * 30);

/** Smooth periodic wobble in [-1, 1] — for idle life, never random jitter. */
export const wave = (frame: number, periodFrames: number, phase = 0): number =>
  Math.sin((frame / periodFrames) * Math.PI * 2 + phase);
